// Correct implementation of PBKDF2-HMAC-SHA256 with proper salt and iteration count
std::vector<std::pair<std::vector<unsigned char>, std::vector<unsigned char>>> hash_passwords(int count, const std::vector<std::string>& passwords) {
    std::vector<std::pair<std::vector<unsigned char>, std::vector<unsigned char>>> result;
    std::random_device rd;
    std::uniform_int_distribution<> dist(0, 255);

    for (int i = 0; i < count; ++i) {
        const std::string& password = passwords[i];
        std::vector<unsigned char> salt(32);
        for (size_t j = 0; j < 32; ++j) {
            salt[j] = dist(rd);
        }

        EVP_PKEY_CTX* ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_PBKDF2, NULL);
        if (!ctx) {
            std::cerr << "Failed to create PBKDF2 context" << std::endl;
            continue;
        }

        if (EVP_PKEY_derive_init(ctx) <= 0) {
            std::cerr << "Failed to initialize PBKDF2" << std::endl;
            EVP_PKEY_CTX_free(ctx);
            continue;
        }

        if (EVP_PKEY_derive_setmd(ctx, EVP_sha256()) <= 0) {
            std::cerr << "Failed to set digest" << std::endl;
            EVP_PKEY_CTX_free(ctx);
            continue;
        }

        if (EVP_PKEY_derive_setkey(ctx, (unsigned char*)password.data(), password.size()) <= 0) {
            std::cerr << "Failed to set key" << std::endl;
            EVP_PKEY_CTX_free(ctx);
            continue;
        }

        if (EVP_PKEY_derive_set_salt(ctx, (unsigned char*)salt.data(), 32) <= 0) {
            std::cerr << "Failed to set salt" << std::endl;
            EVP_PKEY_CTX_free(ctx);
            continue;
        }

        if (EVP_PKEY_derive_set_iterations(ctx, 10000) <= 0) {
            std::cerr << "Failed to set iterations" << std::endl;
            EVP_PKEY_CTX_free(ctx);
            continue;
        }

        std::vector<unsigned char> key(32);
        if (EVP_PKEY_derive(ctx, key.data(), key.size()) <= 0) {
            std::cerr << "Failed to derive key" << std::endl;
            EVP_PKEY_CTX_free(ctx);
            continue;
        }

        EVP_PKEY_CTX_free(ctx);
        result.emplace_back(std::vector<unsigned char>(key.begin(), key.end()),
                            std::vector<unsigned char>(salt.begin(), salt.end()));
    }

    return result;
}
